271:       memcpy(bottom + 2 * x, &pair, sizeof pair);
272:     }
273:   }
274:   canvas_mark_dirty(g_canvas, 2 * b.x0, 2 * b.y0, 2 * (b.x1 - b.x0 + 1),
275:                     2 * (b.y1 - b.y0 + 1));
276: }
